import ee
from datetime import datetime, timedelta
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
roi = ee.Geometry.Point([21.755, 32.762]).buffer(8000)  # ~8 km radius
scale_m = 1000

dates = ["2023-09-08", "2023-09-13"]
dataset_id = 'NOAA/VIIRS/001/VNP46A1'
preferred_bands = ['Gap_Filled_DNB_BRDF-Corrected_NTL', 'DNB_BRDF-Corrected_NTL']
illum_band = 'Moon_Illumination_Fraction'

def get_daily_image(date_str):
    start = ee.Date(date_str)
    end = start.advance(1, 'day')
    col = ee.ImageCollection(dataset_id).filterDate(start, end).filterBounds(roi)
    sz = col.size().getInfo()
    if sz == 0:
        # Try ±1 day recovery
        rec_start = start.advance(-1, 'day')
        rec_end = end.advance(1, 'day')
        rec = ee.ImageCollection(dataset_id).filterDate(rec_start, rec_end).filterBounds(roi)
        rec = rec.map(lambda img: img.set('abs_dt_days', ee.Number(img.date().difference(start, 'day')).abs()))
        rec = rec.sort('abs_dt_days')
        rec_sz = rec.size().getInfo()
        if rec_sz == 0:
            return None, 0, None, None, None, "none"
        img = rec.first()
        used_date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd').getInfo()
        return img, rec_sz, used_date, True, None, "recovered"
    img = col.first()
    used_date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd').getInfo()
    return img, sz, used_date, False, None, "exact"

def get_band(img):
    try:
        names = img.bandNames().getInfo()
    except Exception:
        return None, None
    for b in preferred_bands:
        if b in names:
            return img.select(b), b
    return None, None

def stats_for_date(date_str):
    img, sz, used_date, recovered, _, status = get_daily_image(date_str)
    if img is None:
        return {"ok": False, "reason": "C1", "imgs": 0}
    band_img, band_name = get_band(img)
    if band_img is None:
        return {"ok": False, "reason": "D", "imgs": sz}
    try:
        count = band_img.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=roi,
            scale=scale_m,
            maxPixels=1e9,
        ).get(band_name).getInfo()
        mean_ntl = band_img.reduceRegion(
            reducer=ee.Reducer.mean(),
            geometry=roi,
            scale=scale_m,
            maxPixels=1e9,
        ).get(band_name).getInfo()
        illum = img.select(illum_band).reduceRegion(
            reducer=ee.Reducer.mean(),
            geometry=roi,
            scale=scale_m,
            maxPixels=1e9,
        ).get(illum_band).getInfo()
    except Exception:
        return {"ok": False, "reason": "D", "imgs": sz}
    if count is None or int(count) == 0:
        return {"ok": False, "reason": "C2", "imgs": sz}
    if mean_ntl is None:
        return {"ok": False, "reason": "C3", "imgs": sz}
    try:
        mean_val = float(mean_ntl)
    except Exception:
        return {"ok": False, "reason": "C3", "imgs": sz}
    return {
        "ok": True,
        "imgs": sz,
        "used_date": used_date,
        "recovered": recovered,
        "band": band_name,
        "count": int(count),
        "mean": mean_val,
        "illum": None if illum is None else float(illum),
        "status": status
    }

try:
    s1 = stats_for_date(dates[0])
    s2 = stats_for_date(dates[1])

    print(f"ROI center=32.762,21.755 radius=8km scale={scale_m}m")

    if not s1.get("ok", False):
        print(f"{dates[0]} Images: {s1.get('imgs', 0)}")
        print("Result: " + s1["reason"])
        print("C1" if s1["reason"] == "C1" else s1["reason"])
    elif not s2.get("ok", False):
        print(f"{dates[1]} Images: {s2.get('imgs', 0)}")
        print("Result: " + s2["reason"])
        print("C1" if s2["reason"] == "C1" else s2["reason"])
    else:
        # Print concise evidence
        print(f"{dates[0]} imgs={s1['imgs']} used={s1['used_date']} pix={s1['count']} meanNTL={s1['mean']:.3f} moon={('NA' if s1['illum'] is None else f'{s1['illum']:.2f}')} band={s1['band']}")
        print(f"{dates[1]} imgs={s2['imgs']} used={s2['used_date']} pix={s2['count']} meanNTL={s2['mean']:.3f} moon={('NA' if s2['illum'] is None else f'{s2['illum']:.2f}')} band={s2['band']}")
        decreased = s2['mean'] < s1['mean']
        print(f"Comparison: {s2['mean']:.3f} < {s1['mean']:.3f} => {decreased}")
        print("A" if decreased else "B")
except Exception as e:
    # Any unexpected error (band mismatch, dataset, memory, etc.)
    print("Error encountered.")
    print("D")

