import ee, math
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
roi = ee.Geometry.Point([21.755, 32.762]).buffer(8000)  # ~8 km radius
scale_m = 1000
dates = ["2023-09-08", "2023-09-13"]
dataset_id = 'NOAA/VIIRS/001/VNP46A1'

def get_day_image(day_str):
    start = ee.Date(day_str)
    end = start.advance(1, 'day')
    col = ee.ImageCollection(dataset_id).filterDate(start, end).filterBounds(roi)
    sz = col.size().getInfo()
    if sz > 0:
        return col.median().set('used_date', start.format('YYYY-MM-dd')), sz, start.format('YYYY-MM-dd').getInfo(), False
    # Try ±1 day fallback
    for off in [-1, 1]:
        s = start.advance(off, 'day')
        e = s.advance(1, 'day')
        sub = ee.ImageCollection(dataset_id).filterDate(s, e).filterBounds(roi)
        sub_sz = sub.size().getInfo()
        if sub_sz > 0:
            return sub.median().set('used_date', s.format('YYYY-MM-dd')), sub_sz, s.format('YYYY-MM-dd').getInfo(), True
    return None, 0, None, None

def pick_ntl_band_name(name_list):
    # Prefer gap-filled NTL if present
    cands = [n for n in name_list if ('NTL' in n and 'DNB' in n)]
    if not cands:
        return None
    gf = [n for n in cands if 'Gap' in n or 'Gap_Filled' in n]
    return gf[0] if gf else cands[0]

def compute_stats(day_str):
    img, sz, used_date, recovered = get_day_image(day_str)
    if img is None:
        return {"ok": False, "reason": "C1", "imgs": 0}
    try:
        names = img.bandNames().getInfo()
    except Exception:
        return {"ok": False, "reason": "D", "imgs": sz}
    ntl_name = pick_ntl_band_name(names)
    if ntl_name is None:
        return {"ok": False, "reason": "D", "imgs": sz}
    # Select and rename to a safe key
    ntl = img.select([ntl_name]).rename(['ntl']).updateMask(img.select([ntl_name]).gt(0))
    # Moon illumination if available (robust search)
    moon_name = None
    for n in names:
        if 'Moon' in n and 'Illum' in n:
            moon_name = n
            break
    try:
        counts = ntl.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=roi,
            scale=scale_m,
            maxPixels=1e9,
            tileScale=2
        ).get('ntl').getInfo()
        mean_ntl = ntl.reduceRegion(
            reducer=ee.Reducer.mean(),
            geometry=roi,
            scale=scale_m,
            maxPixels=1e9,
            tileScale=2
        ).get('ntl').getInfo()
        moon = None
        if moon_name:
            moon = img.select([moon_name]).reduceRegion(
                reducer=ee.Reducer.mean(),
                geometry=roi,
                scale=scale_m,
                maxPixels=1e9,
                tileScale=2
            ).get(moon_name).getInfo()
    except Exception:
        return {"ok": False, "reason": "D", "imgs": sz}
    if counts is None or int(counts) == 0:
        return {"ok": False, "reason": "C2", "imgs": sz}
    if mean_ntl is None:
        return {"ok": False, "reason": "C3", "imgs": sz}
    try:
        mv = float(mean_ntl)
        if math.isnan(mv) or math.isinf(mv):
            return {"ok": False, "reason": "C3", "imgs": sz}
        mi = None if moon is None else float(moon)
    except Exception:
        return {"ok": False, "reason": "C3", "imgs": sz}
    return {
        "ok": True, "imgs": sz, "used_date": used_date, "recovered": recovered,
        "band": ntl_name, "count": int(counts), "mean": mv, "illum": mi
    }

try:
    s1 = compute_stats(dates[0])
    s2 = compute_stats(dates[1])

    print(f"ROI center=32.762,21.755 r=8km scale={scale_m}m dataset={dataset_id}")
    if not s1.get("ok", False):
        print(f"{dates[0]} Images: {s1.get('imgs', 0)}")
        print(s1["reason"])
    elif not s2.get("ok", False):
        print(f"{dates[1]} Images: {s2.get('imgs', 0)}")
        print(s2["reason"])
    else:
        m1 = 'NA' if s1['illum'] is None else f"{s1['illum']:.2f}"
        m2 = 'NA' if s2['illum'] is None else f"{s2['illum']:.2f}"
        print(f"{dates[0]} imgs={s1['imgs']} used={s1['used_date']} pix={s1['count']} meanNTL={s1['mean']:.3f} moon={m1} band='{s1['band']}' ({'rec' if s1['recovered'] else 'exact'})")
        print(f"{dates[1]} imgs={s2['imgs']} used={s2['used_date']} pix={s2['count']} meanNTL={s2['mean']:.3f} moon={m2} band='{s2['band']}' ({'rec' if s2['recovered'] else 'exact'})")
        decreased = s2['mean'] < s1['mean']
        print(f"Comparison: {s2['mean']:.3f} < {s1['mean']:.3f} => {decreased}")
        print("A" if decreased else "B")
except Exception:
    print("Error encountered.")
    print("D")
